function carBrand(car){if(car.details?.brand)return car.details.brand;return Object.keys(carModels||{}).sort((a,b)=>b.length-a.length).find(brand=>car.name===brand||car.name.startsWith(`${brand} `))||car.name.split(' ')[0]}
