document.querySelectorAll('.sale-mode-btn').forEach(button=>button.addEventListener('click',()=>{const auction=button.dataset.saleMode==='auction';document.querySelectorAll('.sale-mode-btn').forEach(item=>item.classList.toggle('active',item===button));listingForm.elements.saleMode.value=button.dataset.saleMode;document.querySelector('#auctionSettings').hidden=!auction;document.querySelector('#priceHint').textContent=auction?'Это будет стартовая цена аукциона':'Укажите стоимость автомобиля'}));
function showWizardStep(step){wizardStep=step;document.querySelectorAll('.wizard-step').forEach((x,i)=>x.classList.toggle('active',i===step));document.querySelectorAll('.wizard-progress i').forEach((x,i)=>x.classList.toggle('done',i<=step));document.querySelector('#stepLabel').textContent=`Шаг ${step+1} из 4`;document.querySelector('#wizardBack').style.visibility=step?'visible':'hidden';document.querySelector('#wizardNext').textContent=step===3?'Опубликовать':'Продолжить →'}
function openWizard(authenticated=false){if(!authenticated&&window.vklucheAuth&&!window.vklucheAuth.require(()=>openWizard(true)))return;const role=window.vklucheAuth?.getRole?.()||'buyer';if(!['seller','admin'].includes(role))return toast('Размещать автомобили могут продавцы и администраторы');modal.classList.add('open');document.body.style.overflow='hidden';listingForm.style.display='block';document.querySelector('#publishSuccess').style.display='none';showWizardStep(0)}
function closeWizard(){modal.classList.remove('open');document.body.style.overflow=''}
document.querySelectorAll('.open-modal').forEach(b=>b.addEventListener('click',openWizard));document.querySelector('.modal-close').addEventListener('click',closeWizard);document.querySelector('#modal .modal-backdrop').addEventListener('click',closeWizard);
document.querySelector('#wizardBack').addEventListener('click',()=>showWizardStep(Math.max(0,wizardStep-1)));document.querySelector('#wizardNext').addEventListener('click',()=>{const step=document.querySelector(`.wizard-step[data-step="${wizardStep}"]`),required=[...step.querySelectorAll('[required]')];if(!required.every(x=>x.reportValidity()))return;if(wizardStep<3){showWizardStep(wizardStep+1);return}publishListing()});
function publishListing(){
  const d=Object.fromEntries(new FormData(listingForm)),brand=brandSelect.value===otherValue?d.customBrand.trim():brandSelect.value,model=modelSelect.value===otherValue?d.customModel.trim():modelSelect.value,img=uploadedPhotos[0]||'https://images.unsplash.com/photo-1494976388531-d1058494cdd8?auto=format&fit=crop&w=1000&q=85';
  const auction=d.saleMode==='auction'?{status:'active',startPrice:+d.price,reservePrice:+d.reservePrice||0,bidStep:+d.bidStep,endsAt:Date.now()+(+d.auctionDuration*60*60*1000),autoExtend:d.autoExtend==='on',bids:[]}:null;
  const ownerId=window.vklucheAuth?.getUser()?.id||null,vin=d.vin.trim().toUpperCase(),diagnostics={body:d.diagnosticBody==='on',technical:d.diagnosticTechnical==='on',legal:d.diagnosticLegal==='on',mileage:d.diagnosticMileage==='on'},car={id:Date.now(),ownerId,name:`${brand} ${model}`,price:+d.price,year:+d.year,km:+d.km?`${new Intl.NumberFormat('ru-RU').format(+d.km)} км`:'Новый',engine:d.volume?`${d.volume} л / ${d.power||'—'} л.с.`:'Двигатель не указан',city:d.city,date:'только что',type:[d.condition,d.body==='Кроссовер'?'suv':'',d.engineType==='electric'?'electric':''].filter(Boolean),badge:auction?'Аукцион':'Новое объявление',img,auction,listingStatus:'published',verificationStatus:'submitted',details:{brand,model,body:d.body,condition:d.condition,engineType:d.engineType,gearbox:d.gearbox,drive:d.drive,color:d.color,owners:d.owners,description:d.description,seller:d.seller,phone:d.phone,vin,registrationPlate:d.registrationPlate.trim().toUpperCase(),diagnostics,documents:[...uploadedDocuments]}};
  const own=JSON.parse(localStorage.getItem('vkluche-listings')||'[]');own.unshift(car);localStorage.setItem('vkluche-listings',JSON.stringify(own));cars.unshift(car);const client=window.vklucheAuth?.getClient();if(client&&ownerId)client.from('listings').insert({external_id:`manual:${car.id}`,owner_id:ownerId,data:car,status:'published',verification_status:'submitted',vin,registration_plate:car.details.registrationPlate||null}).select('id').single().then(({data,error})=>{if(data){car.listingId=data.id;const stored=JSON.parse(localStorage.getItem('vkluche-listings')||'[]'),item=stored.find(x=>String(x.id)===String(car.id));if(item){item.listingId=data.id;localStorage.setItem('vkluche-listings',JSON.stringify(stored))}}else if(error)toast(`Объявление сохранено только на устройстве: ${error.message}`)});listingForm.style.display='none';document.querySelector('#publishSuccess').style.display='block';document.querySelector('#publishSuccess h3').textContent=auction?'Аукцион запущен!':'Объявление опубликовано!';render();renderAuctionSection();document.querySelector('#favCount').textContent=saved.size;window.lastPublished=car;
}
document.querySelector('#viewPublished').addEventListener('click',()=>{closeWizard();document.querySelector('#catalog').scrollIntoView();setTimeout(()=>{openDetail(window.lastPublished);renderAuction(window.lastPublished)},350)});
const feedModal=document.querySelector('#feedModal'),feedForm=document.querySelector('#feedForm'),feedFile=document.querySelector('#feedFile'),feedUrl=document.querySelector('#feedUrl'),feedReport=document.querySelector('#feedReport');
function openFeed(){feedModal.classList.add('open');document.body.style.overflow='hidden';feedReport.className='feed-report';feedReport.textContent='';loadFeedSources()}
function closeFeed(){feedModal.classList.remove('open');document.body.style.overflow=''}
document.querySelectorAll('.open-feed').forEach(button=>button.addEventListener('click',openFeed));document.querySelector('#feedModal .modal-close').addEventListener('click',closeFeed);document.querySelector('#feedModal .modal-backdrop').addEventListener('click',closeFeed);document.querySelector('.feed-cancel').addEventListener('click',closeFeed);
feedFile.addEventListener('change',()=>{document.querySelector('#feedFileName').textContent=feedFile.files[0]?.name||'Выберите файл с объявлениями';if(feedFile.files.length)feedUrl.value=''});
function feedText(ad,name){return ad.querySelector(name)?.textContent.trim()||''}
function feedImages(ad){return [...ad.querySelectorAll('Images > Image')].map(image=>image.getAttribute('url')||image.textContent.trim()).filter(Boolean)}
function feedCar(ad){
  const externalId=feedText(ad,'Id'),make=feedText(ad,'Make'),model=feedText(ad,'Model'),price=Number(feedText(ad,'Price')),year=Number(feedText(ad,'Year'));
  if(!externalId||!make||!model||!price||!year)throw new Error(`Объявление ${externalId||'без Id'}: обязательны Id, Make, Model, Year и Price`);
  const mileage=Number(feedText(ad,'Kilometrage')||feedText(ad,'Mileage')),power=feedText(ad,'Power'),volume=feedText(ad,'EngineSize'),images=feedImages(ad),condition=feedText(ad,'Condition').toLowerCase(),body=feedText(ad,'BodyType'),address=feedText(ad,'City')||feedText(ad,'Address')||feedText(ad,'Region')||'Город не указан';
  const engineType=feedText(ad,'EngineType')||feedText(ad,'FuelType');
  return{id:`avito:${externalId}`,externalId,source:'avito-feed',name:`${make} ${model}`,price,year,km:mileage?`${new Intl.NumberFormat('ru-RU').format(mileage)} км`:'Новый',engine:volume?`${volume} л / ${power||'—'} л.с.`:power?`${power} л.с.`:'Двигатель не указан',city:address,date:'из фида',type:[condition.includes('нов')?'new':'used',body.toLowerCase().includes('внедорож')||body.toLowerCase().includes('кроссов')?'suv':'',/элект|electric|ev/i.test(engineType)?'electric':''].filter(Boolean),badge:'Автозагрузка',img:images[0]||'https://images.unsplash.com/photo-1494976388531-d1058494cdd8?auto=format&fit=crop&w=1000&q=85',details:{brand:make,model,engineType,gearbox:feedText(ad,'Transmission'),drive:feedText(ad,'DriveType'),color:feedText(ad,'Color'),description:feedText(ad,'Description'),seller:feedText(ad,'ManagerName')||feedText(ad,'ContactName'),phone:feedText(ad,'ContactPhone'),images}};
}
function importFeedXml(xmlText){const xml=new DOMParser().parseFromString(xmlText,'application/xml');if(xml.querySelector('parsererror'))throw new Error('XML-файл повреждён или имеет неверный формат');const ads=[...xml.querySelectorAll('Ads > Ad')];if(!ads.length)throw new Error('В фиде не найдены элементы Ads → Ad');const own=JSON.parse(localStorage.getItem('vkluche-listings')||'[]'),errors=[];let added=0,updated=0;ads.forEach(ad=>{try{const car=feedCar(ad),ownIndex=own.findIndex(item=>item.source==='avito-feed'&&String(item.id)===String(car.id)),carsIndex=cars.findIndex(item=>item.source==='avito-feed'&&String(item.id)===String(car.id));if(ownIndex>=0){own[ownIndex]=car;updated++}else{own.push(car);added++}if(carsIndex>=0)cars[carsIndex]=car;else cars.unshift(car)}catch(error){errors.push(error.message)}});localStorage.setItem('vkluche-listings',JSON.stringify(own));render();return{total:ads.length,added,updated,errors}}
feedForm.addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#importFeed');button.disabled=true;button.textContent='Загрузка…';try{let xmlText;if(feedFile.files[0])xmlText=await feedFile.files[0].text();else if(feedUrl.value.trim()){const response=await fetch(feedUrl.value.trim());if(!response.ok)throw new Error(`Сервер фида ответил с кодом ${response.status}`);xmlText=await response.text()}else throw new Error('Выберите XML-файл или укажите ссылку на фид');const result=importFeedXml(xmlText);feedReport.className=`feed-report ${result.errors.length===result.total?'error':'success'}`;feedReport.textContent=`Обработано: ${result.total}. Добавлено: ${result.added}, обновлено: ${result.updated}, ошибок: ${result.errors.length}. ${result.errors.slice(0,3).join(' ')}`;if(result.added||result.updated)document.querySelector('#catalog').scrollIntoView()}catch(error){feedReport.className='feed-report error';feedReport.textContent=`Не удалось загрузить фид: ${error.message}`}finally{button.disabled=false;button.textContent='Загрузить объявления'}});
const autoFeedForm=document.querySelector('#autoFeedForm'),feedSources=document.querySelector('#feedSources'),autoFeedNotice=document.querySelector('#autoFeedNotice');
async function adminContext(){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user)return null;const{data}=await client.from('profiles').select('role').eq('id',user.id).maybeSingle();return data?.role==='admin'?{client,user}:null}
async function loadFeedSources(){feedSources.innerHTML='';autoFeedForm.classList.remove('allowed');autoFeedNotice.style.display='block';const context=await adminContext();if(!context){autoFeedNotice.textContent=window.vklucheAuth?.getUser()?'Управление фидами доступно только администратору.':'Войдите как администратор, чтобы управлять источниками.';return}autoFeedForm.classList.add('allowed');autoFeedNotice.style.display='none';const{data,error}=await context.client.from('feed_sources').select('*').order('created_at',{ascending:false});if(error){autoFeedNotice.style.display='block';autoFeedNotice.textContent=`Не удалось загрузить источники: ${error.message}`;return}feedSources.innerHTML=data.length?data.map(source=>`<div class="feed-source"><span><b>${escapeHtml(source.name)}</b><small>${source.interval_minutes} мин · ${source.last_run_at?`последняя проверка ${new Date(source.last_run_at).toLocaleString('ru-RU')}`:'ещё не запускался'}</small><small class="feed-source-status ${source.last_status||''}">${source.last_status==='success'?'Загружен успешно':source.last_error?escapeHtml(source.last_error):'Ожидает запуска'}</small></span><button type="button" data-sync-feed="${source.id}">Загрузить сейчас</button></div>`).join(''):'<div class="auto-feed-login">Автоматических источников пока нет.</div>'}
autoFeedForm.addEventListener('submit',async event=>{event.preventDefault();const context=await adminContext();if(!context)return window.vklucheAuth?.require(()=>openFeed());const values=new FormData(autoFeedForm),button=event.submitter;button.disabled=true;button.textContent='Добавление…';const{error}=await context.client.from('feed_sources').insert({name:values.get('name').trim(),url:values.get('url').trim(),interval_minutes:+values.get('interval'),missing_threshold:+values.get('threshold'),created_by:context.user.id});button.disabled=false;button.textContent='Добавить автоматический фид';if(error)return toast(`Не удалось добавить: ${error.message}`);autoFeedForm.reset();toast('Автоматический фид добавлен');loadFeedSources()});
feedSources.addEventListener('click',async event=>{const button=event.target.closest('[data-sync-feed]');if(!button)return;const context=await adminContext();if(!context)return toast('Нужны права администратора');button.disabled=true;button.textContent='Загрузка…';const{data,error}=await context.client.functions.invoke('import-feeds',{body:{sourceId:button.dataset.syncFeed}});button.disabled=false;button.textContent='Загрузить сейчас';if(error||data?.results?.[0]?.error)toast(`Ошибка импорта: ${data?.results?.[0]?.error||error.message}`);else{toast(`Импортировано: ${data.results[0].total}`);await loadRemoteListings();render()}loadFeedSources()});
