async function loadNotifications(){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user)return;const{data}=await client.from('notifications').select('*').order('created_at',{ascending:false}).limit(30);const rows=data||[],unread=rows.filter(item=>!item.read_at).length;document.querySelector('#notificationCount').textContent=unread||'';document.querySelector('#notificationList').innerHTML=rows.length?rows.map(item=>`<article class="${item.read_at?'':'unread'}"><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.body)}</span><small>${new Date(item.created_at).toLocaleString('ru-RU')}</small></article>`).join(''):'<p>Новых уведомлений нет</p>'}
