function auctionBest(auction){return Math.max(auction.startPrice,...auction.bids.map(bid=>bid.amount))}
function auctionLeft(endsAt){const left=Math.max(0,endsAt-Date.now()),hours=Math.floor(left/3600000),minutes=Math.floor(left%3600000/60000),seconds=Math.floor(left%60000/1000);return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`}
function renderAuctionSection(){const visible=cars.filter(car=>car.auction&&['scheduled','active'].includes(car.auction.status)&&car.auction.endsAt>Date.now());auctionGrid.innerHTML=visible.map(car=>{const scheduled=car.auction.status==='scheduled',target=scheduled?car.auction.startsAt:car.auction.endsAt;return`<article class="auction-card" data-auction-car="${escapeHtml(car.id)}"><div class="auction-card-image"><img src="${car.img}" alt="${escapeHtml(car.name)}"><span>⚡ ${scheduled?'Скоро':'Аукцион'}</span><b data-auction-countdown="${target}">${scheduled?'Старт через ':''}${auctionLeft(target)}</b></div><div class="auction-card-body"><h3>${escapeHtml(car.name)}</h3><div class="auction-card-price"><span>${scheduled?'Стартовая цена':'Лучшая ставка'}</span><strong>${money(auctionBest(car.auction))}</strong></div><div class="auction-card-meta"><span>${car.year} · ${car.km}</span><span>${car.auction.bids.length} предложений</span></div><button type="button">${scheduled?'Напомнить о начале':'Участвовать в торгах'} →</button></div></article>`}).join('');auctionGrid.style.display=visible.length?'grid':'none';auctionEmpty.style.display=visible.length?'none':'flex'}
auctionGrid.addEventListener('click',event=>{const card=event.target.closest('[data-auction-car]');if(!card)return;const car=cars.find(item=>String(item.id)===card.dataset.auctionCar);if(car){openDetail(car);renderAuction(car)}});
function persistAuctionCar(car){const own=JSON.parse(localStorage.getItem('vkluche-listings')||'[]'),index=own.findIndex(item=>String(item.id)===String(car.id));if(index>=0){own[index]=car;localStorage.setItem('vkluche-listings',JSON.stringify(own))}const overrides=JSON.parse(localStorage.getItem('vkluche-auction-overrides')||'{}');overrides[car.id]={auction:car.auction,price:car.price,badge:car.badge};localStorage.setItem('vkluche-auction-overrides',JSON.stringify(overrides))}
