async function loadRemoteListings(){
  const client=window.vklucheAuth?.getClient();if(!client)return;
  const{data,error}=await client.from('listings').select('id,owner_id,data,status,verification_status,vin,registration_plate').eq('active',true).eq('status','published').order('updated_at',{ascending:false});
  if(error){console.warn(`Каталог Supabase пока недоступен: ${error.message}`);return}
  for(let i=cars.length-1;i>=0;i--)if(cars[i].source==='automatic-feed'||cars[i].listingId)cars.splice(i,1);
  const remoteCars=data.map(row=>({...row.data,listingId:row.id,ownerId:row.owner_id,listingStatus:row.status,verificationStatus:row.verification_status,details:{...(row.data.details||{}),vin:row.vin||row.data.details?.vin,registrationPlate:row.registration_plate||row.data.details?.registrationPlate}}));
  const{data:auctionRows,error:auctionError}=await client.from('auctions').select('*,auction_bids!auction_bids_auction_id_fkey(*),auction_deals(*),auction_audit_log(*)').in('listing_id',data.map(row=>row.id));
  if(auctionError)console.warn(`Аукционы пока недоступны: ${auctionError.message}`);
  (auctionRows||[]).forEach(row=>{const car=remoteCars.find(item=>item.listingId===row.listing_id);if(!car)return;const deals=[...(row.auction_deals||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));car.auction={id:row.id,status:row.status,startPrice:+row.start_price,reservePrice:+row.reserve_price,bidStep:+row.bid_step,startsAt:new Date(row.starts_at).getTime(),endsAt:new Date(row.ends_at).getTime(),autoExtend:row.auto_extend,winnerId:row.winner_bid_id,deal:deals[0]||null,events:[...(row.auction_audit_log||[])].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)),bids:(row.auction_bids||[]).map(bid=>({id:bid.id,userId:bid.bidder_id,buyer:'Участник',amount:+bid.amount,comment:bid.comment,createdAt:new Date(bid.created_at).getTime()}))};car.price=auctionBest(car.auction);car.badge={scheduled:'Аукцион скоро',active:'Аукцион',awaiting_seller:'Выбор продавца',awaiting_buyer:'Ожидается покупатель',deal_confirmed:'Сделка подтверждена',no_sale:'Без сделки'}[row.status]||'Аукцион завершён'});
  cars.unshift(...remoteCars);document.querySelector('#liveListingCount').textContent=cars.length;document.querySelector('#catalogTrustLabel').textContent=`В каталоге ${cars.length} ${cars.length===1?'автомобиль':'автомобилей'}`;fillFilterCities();render();renderAuctionSection()
}
let realtimeChannel=null;function setupRealtime(){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user)return;if(realtimeChannel)client.removeChannel(realtimeChannel);realtimeChannel=client.channel(`vkluche-auctions-${user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'auctions'},()=>loadRemoteListings()).on('postgres_changes',{event:'INSERT',schema:'public',table:'auction_bids'},()=>loadRemoteListings()).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:`user_id=eq.${user.id}`},()=>loadNotifications()).subscribe()}
function renderVehicleTrust(car){if(!car)return;const d=car.details||{},diagnostics=d.diagnostics||{},verified=car.verificationStatus==='verified',submitted=car.verificationStatus==='submitted',badge=document.querySelector('#verificationBadge');badge.className=verified?'verified':submitted?'submitted':'unverified';badge.textContent=verified?'Проверено ВКЛЮЧЕ':submitted?'Ожидает проверки':'Не проверено';document.querySelector('#verificationSummary').textContent=verified?'VIN и сведения об автомобиле подтверждены площадкой.':submitted?'VIN предоставлен продавцом и отправлен на проверку.':'Сведения указаны продавцом и пока не подтверждены площадкой.';const checks=[['VIN указан',Boolean(d.vin)],['Осмотр кузова',diagnostics.body],['Техническая диагностика',diagnostics.technical],['Документы',diagnostics.legal],['Пробег',diagnostics.mileage]];document.querySelector('#detailTrustChecks').innerHTML=checks.map(([label,ok])=>`<span class="${ok?'done':''}">${ok?'✓':'—'} ${label}</span>`).join('');document.querySelector('.detail-aside .seller span').textContent=verified?'Автомобиль проверен площадкой':'Данные продавца не проверены'}
new MutationObserver(()=>{if(detail.classList.contains('open'))renderVehicleTrust(currentCar)}).observe(detail,{attributes:true,attributeFilter:['class']});
